// Package coll implements the `coll` template-function namespace: helpers to
// manipulate and query collections (lists and maps).
package coll

import (
	"fmt"
	"reflect"
	"sort"

	"gomplate/internal/num"
)

// NS returns the coll namespace: a pointer to a struct whose methods are the
// namespace functions.
func NS() any {
	return &ns{}
}

// Aliases returns the top-level alias functions for this namespace.
func Aliases() map[string]any {
	n := &ns{}
	return map[string]any{
		"dict":     n.Dict,
		"has":      n.Has,
		"jsonpath": n.JSONPath,
		"jq":       n.JQ,
		"keys":     n.Keys,
		"values":   n.Values,
		"append":   n.Append,
		"prepend":  n.Prepend,
		"uniq":     n.Uniq,
		"flatten":  n.Flatten,
		"reverse":  n.Reverse,
		"sort":     n.Sort,
		"merge":    n.Merge,
		"set":      n.Set,
		"unset":    n.Unset,
		"slice":    n.GoSlice,
	}
}

type ns struct{}

// toString converts a value to a string the way the reference tool does for
// map keys: strings pass through, nil becomes "nil", everything else uses
// fmt's %v verb.
func toString(v any) string {
	if v == nil {
		return "nil"
	}
	if s, ok := v.(string); ok {
		return s
	}
	return fmt.Sprintf("%v", v)
}

// toSlice converts any slice or array into a []any. The error text matches
// the reference tool (which formats a reflect.Value with %T).
func toSlice(list any) ([]any, error) {
	v := reflect.ValueOf(list)
	if !v.IsValid() || (v.Kind() != reflect.Slice && v.Kind() != reflect.Array) {
		return nil, fmt.Errorf("expected an array or slice, but got a %T", v)
	}
	out := make([]any, v.Len())
	for i := 0; i < v.Len(); i++ {
		out[i] = v.Index(i).Interface()
	}
	return out, nil
}

// Dict creates a map with string keys from key/value pairs. An odd trailing
// argument gets an empty-string value. All keys are converted to strings.
func (n *ns) Dict(values ...any) (map[string]any, error) {
	dict := make(map[string]any, (len(values)+1)/2)
	for i := 0; i < len(values); i += 2 {
		key := toString(values[i])
		if i+1 < len(values) {
			dict[key] = values[i+1]
		} else {
			dict[key] = ""
		}
	}
	return dict, nil
}

// Slice creates a []any from the given elements.
func (n *ns) Slice(args ...any) []any {
	out := make([]any, len(args))
	copy(out, args)
	return out
}

// GoSlice exposes Go's text/template `slice` function:
// "slice x 1 2" is x[1:2], "slice x" is x[:], "slice x 1" is x[1:], and
// "slice x 1 2 3" is x[1:2:3]. The first argument must be a string, slice,
// or array.
func (n *ns) GoSlice(item any, indexes ...any) (any, error) {
	v := reflect.ValueOf(item)
	if !v.IsValid() {
		return nil, fmt.Errorf("slice of untyped nil")
	}
	if len(indexes) > 3 {
		return nil, fmt.Errorf("too many slice indexes: %d", len(indexes))
	}
	var capacity int
	switch v.Kind() {
	case reflect.String:
		if len(indexes) == 3 {
			return nil, fmt.Errorf("cannot 3-index slice a string")
		}
		capacity = v.Len()
	case reflect.Array, reflect.Slice:
		capacity = v.Cap()
	default:
		return nil, fmt.Errorf("can't slice item of type %s", v.Type())
	}
	// set default values for cases item[:], item[i:]
	idx := [3]int{0, v.Len()}
	for i, index := range indexes {
		x, err := indexArg(index, capacity)
		if err != nil {
			return nil, err
		}
		idx[i] = x
	}
	// given item[i:j], make sure i <= j
	if idx[0] > idx[1] {
		return nil, fmt.Errorf("invalid slice index: %d > %d", idx[0], idx[1])
	}
	if len(indexes) < 3 {
		return v.Slice(idx[0], idx[1]).Interface(), nil
	}
	// given item[i:j:k], make sure i <= j <= k
	if idx[1] > idx[2] {
		return nil, fmt.Errorf("invalid slice index: %d > %d", idx[1], idx[2])
	}
	return v.Slice3(idx[0], idx[1], idx[2]).Interface(), nil
}

func indexArg(index any, capacity int) (int, error) {
	v := reflect.ValueOf(index)
	var x int64
	switch v.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		x = v.Int()
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		x = int64(v.Uint())
	case reflect.Invalid:
		return 0, fmt.Errorf("cannot index slice/array with nil")
	default:
		return 0, fmt.Errorf("cannot index slice/array with type %s", v.Type())
	}
	if x < 0 || int(x) < 0 || int(x) > capacity {
		return 0, fmt.Errorf("index out of range: %d", x)
	}
	return int(x), nil
}

// Has reports whether a map has the given key, or a slice/array contains the
// given value.
func (n *ns) Has(in any, item string) bool {
	v := reflect.ValueOf(in)
	switch v.Kind() {
	case reflect.Map:
		key := reflect.ValueOf(item)
		if key.Type().AssignableTo(v.Type().Key()) {
			return v.MapIndex(key).IsValid()
		}
		// fall back to comparing stringified keys
		for _, k := range v.MapKeys() {
			if toString(k.Interface()) == item {
				return true
			}
		}
		return false
	case reflect.Array, reflect.Slice:
		for i := 0; i < v.Len(); i++ {
			e := v.Index(i).Interface()
			if s, ok := e.(string); ok && s == item {
				return true
			}
		}
		return false
	}
	return false
}

// Index returns the result of indexing the given map, slice, array or string
// by the given key(s) or index(es). The last argument is the collection; all
// preceding arguments are indexes applied in order.
func (n *ns) Index(indexes ...any) (any, error) {
	if len(indexes) < 2 {
		return nil, fmt.Errorf("wrong number of args: wanted at least 2, got %d", len(indexes))
	}
	item := indexes[len(indexes)-1]
	indexes = indexes[:len(indexes)-1]

	v := reflect.ValueOf(item)
	if !v.IsValid() {
		return nil, fmt.Errorf("index of untyped nil")
	}
	for _, index := range indexes {
		switch v.Kind() {
		case reflect.Map:
			key, ok := index.(string)
			if !ok {
				return nil, fmt.Errorf("value has type %s; should be string", reflect.TypeOf(index))
			}
			e := v.MapIndex(reflect.ValueOf(key))
			if !e.IsValid() {
				return nil, fmt.Errorf("map has no key %s", key)
			}
			v = e
		case reflect.Slice, reflect.Array, reflect.String:
			i, err := indexArg(index, v.Len()-1)
			if err != nil {
				return nil, err
			}
			v = v.Index(i)
		default:
			return nil, fmt.Errorf("can't index item of type %s", v.Type())
		}
		if v.Kind() == reflect.Interface {
			v = reflect.ValueOf(v.Interface())
			if !v.IsValid() {
				return nil, fmt.Errorf("index of untyped nil")
			}
		}
	}
	return v.Interface(), nil
}

// Keys returns the keys of one or more maps, ordered first by map position,
// then alphabetically.
func (n *ns) Keys(in ...map[string]any) ([]string, error) {
	if len(in) == 0 {
		return nil, fmt.Errorf("need at least one argument")
	}
	out := []string{}
	for _, m := range in {
		keys := make([]string, 0, len(m))
		for k := range m {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		out = append(out, keys...)
	}
	return out, nil
}

// Values returns the values of one or more maps, ordered first by map
// position, then alphabetically by key.
func (n *ns) Values(in ...map[string]any) ([]any, error) {
	if len(in) == 0 {
		return nil, fmt.Errorf("need at least one argument")
	}
	out := []any{}
	for _, m := range in {
		keys := make([]string, 0, len(m))
		for k := range m {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			out = append(out, m[k])
		}
	}
	return out, nil
}

// Append returns a new list with value appended to the end of list.
func (n *ns) Append(v any, list any) ([]any, error) {
	l, err := toSlice(list)
	if err != nil {
		return nil, err
	}
	return append(l, v), nil
}

// Prepend returns a new list with value prepended to the beginning of list.
func (n *ns) Prepend(v any, list any) ([]any, error) {
	l, err := toSlice(list)
	if err != nil {
		return nil, err
	}
	return append([]any{v}, l...), nil
}

// Uniq removes duplicate values from the list, without changing order.
func (n *ns) Uniq(list any) ([]any, error) {
	l, err := toSlice(list)
	if err != nil {
		return nil, err
	}
	out := []any{}
	for _, e := range l {
		dup := false
		for _, o := range out {
			if reflect.DeepEqual(e, o) {
				dup = true
				break
			}
		}
		if !dup {
			out = append(out, e)
		}
	}
	return out, nil
}

// Flatten flattens a nested list. With two arguments the first is the maximum
// depth to flatten (-1 or any negative value for infinite depth).
func (n *ns) Flatten(args ...any) ([]any, error) {
	var depth int64
	var list any
	switch len(args) {
	case 1:
		depth = -1
		list = args[0]
	case 2:
		depth = num.ToInt64(args[0])
		list = args[1]
	default:
		return nil, fmt.Errorf("wrong number of args: wanted 1 or 2, got %d", len(args))
	}
	l, err := toSlice(list)
	if err != nil {
		return nil, err
	}
	return flatten(depth, l), nil
}

func flatten(depth int64, list []any) []any {
	out := []any{}
	for _, e := range list {
		v := reflect.ValueOf(e)
		isList := v.IsValid() && (v.Kind() == reflect.Slice || v.Kind() == reflect.Array)
		if isList && depth != 0 {
			sub, _ := toSlice(e)
			out = append(out, flatten(depth-1, sub)...)
		} else {
			out = append(out, e)
		}
	}
	return out
}

// Reverse returns a new list with the elements of list in reverse order.
func (n *ns) Reverse(list any) ([]any, error) {
	l, err := toSlice(list)
	if err != nil {
		return nil, err
	}
	out := make([]any, len(l))
	for i, e := range l {
		out[len(l)-1-i] = e
	}
	return out, nil
}

// Sort sorts a list using natural sort order. Inputs that are not sortable
// (mixed or unsortable element types) are returned unmodified. With two
// arguments, the first is the key to sort maps by.
func (n *ns) Sort(args ...any) (any, error) {
	var key string
	var list any
	switch len(args) {
	case 1:
		list = args[0]
	case 2:
		key, _ = args[0].(string)
		list = args[1]
	default:
		return nil, fmt.Errorf("wrong number of args: wanted 1 or 2, got %d", len(args))
	}
	if list == nil {
		return []any{}, nil
	}
	l, err := toSlice(list)
	if err != nil {
		return nil, err
	}

	// extract the values to compare
	vals := make([]any, len(l))
	copy(vals, l)
	if key != "" {
		for i, e := range l {
			m, ok := e.(map[string]any)
			if !ok {
				return l, nil
			}
			v, ok := m[key]
			if !ok {
				return l, nil
			}
			vals[i] = v
		}
	}

	kind := sortKind(vals)
	if kind == reflect.Invalid {
		return l, nil
	}
	idx := make([]int, len(l))
	for i := range idx {
		idx[i] = i
	}
	sort.SliceStable(idx, func(a, b int) bool {
		return less(kind, vals[idx[a]], vals[idx[b]])
	})
	out := make([]any, len(l))
	for i, j := range idx {
		out[i] = l[j]
	}
	return out, nil
}

// sortKind returns the common reflect kind category of all values, or
// reflect.Invalid if the values are not homogeneously sortable.
func sortKind(vals []any) reflect.Kind {
	kind := reflect.Invalid
	for _, v := range vals {
		var k reflect.Kind
		switch v.(type) {
		case string:
			k = reflect.String
		case float32, float64:
			k = reflect.Float64
		case int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64:
			k = reflect.Int64
		default:
			return reflect.Invalid
		}
		if kind == reflect.Invalid {
			kind = k
		} else if kind != k {
			return reflect.Invalid
		}
	}
	return kind
}

func less(kind reflect.Kind, a, b any) bool {
	switch kind {
	case reflect.String:
		return a.(string) < b.(string)
	case reflect.Float64:
		return num.ToFloat64(a) < num.ToFloat64(b)
	default:
		return num.ToInt64(a) < num.ToInt64(b)
	}
}

// Merge merges maps together by overriding srcs with dst. Nested maps are
// merged recursively. Neither dst nor any src is modified.
func (n *ns) Merge(dst map[string]any, srcs ...map[string]any) (map[string]any, error) {
	out := map[string]any{}
	// srcs first, in reverse precedence order (rightmost loses first)
	for i := len(srcs) - 1; i >= 0; i-- {
		out = mergeInto(out, srcs[i])
	}
	out = mergeInto(out, dst)
	return out, nil
}

// mergeInto merges src into dst, where dst's existing values win. Nested
// map[string]any values are merged recursively. Returns a new map; neither
// input is modified.
func mergeInto(dst, src map[string]any) map[string]any {
	out := make(map[string]any, len(dst)+len(src))
	for k, v := range src {
		out[k] = v
	}
	for k, v := range dst {
		if existing, ok := out[k]; ok {
			em, eok := existing.(map[string]any)
			vm, vok := v.(map[string]any)
			if eok && vok {
				out[k] = mergeInto(vm, em)
				continue
			}
		}
		out[k] = v
	}
	return out
}

// pickOmitKeys validates and flattens the key arguments shared by Pick and
// Omit. The last argument must be the map.
func pickOmitKeys(fname string, args []any) ([]string, map[string]any, error) {
	if len(args) < 2 {
		return nil, nil, fmt.Errorf("wrong number of args: wanted 2 or more, got %d", len(args))
	}
	m, ok := args[len(args)-1].(map[string]any)
	if !ok {
		return nil, nil, fmt.Errorf("wrong map type: must be map[string]any, got %T", args[len(args)-1])
	}
	keys := []string{}
	for _, a := range args[:len(args)-1] {
		if s, ok := a.(string); ok {
			keys = append(keys, s)
			continue
		}
		v := reflect.ValueOf(a)
		if v.IsValid() && (v.Kind() == reflect.Slice || v.Kind() == reflect.Array) {
			for i := 0; i < v.Len(); i++ {
				e := v.Index(i).Interface()
				s, ok := e.(string)
				if !ok {
					return nil, nil, fmt.Errorf("wrong key type: must be string, got %T (%v)", e, e)
				}
				keys = append(keys, s)
			}
			continue
		}
		return nil, nil, fmt.Errorf("wrong key type: must be string, got %T (%v)", a, a)
	}
	return keys, m, nil
}

