package coll

import (
	"fmt"
	"strconv"
	"strings"
)

// This is a small, self-contained subset of JSONPath (the reference tool uses
// a full external JSONPath library, which cannot be reproduced with the Go
// standard library alone). Supported syntax:
//
//	$               root
//	.name  ['name'] child (object key)
//	[n]             child (array index, negative counts from the end)
//	.*  [*]         wildcard (all object values / array elements)
//	..name  ..*     recursive descent
//
// Expressions using filters (?(...)), unions, or script fragments are not
// supported and return a parse error.

type jpSegment struct {
	kind     int // jpChild, jpIndex, jpWildcard, jpRecurse
	name     string
	index    int
	recChild *jpSegment // for jpRecurse: the child to look for
}

const (
	jpChild = iota
	jpIndex
	jpWildcard
	jpRecurse
)

// JSONPath extracts portions of the input using a JSONPath expression.
// Multiple matches are returned as an array; a single match is unwrapped.
func (n *ns) JSONPath(expression string, in any) (any, error) {
	segs, err := parseJSONPath(expression)
	if err != nil {
		return nil, fmt.Errorf("couldn't parse JSONPath %s: %s", expression, err)
	}
	matches := []any{in}
	for _, s := range segs {
		matches = jpApply(s, matches)
	}
	switch len(matches) {
	case 0:
		name := expression
		if len(segs) > 0 {
			last := segs[len(segs)-1]
			switch last.kind {
			case jpChild:
				name = last.name
			case jpRecurse:
				name = last.recChild.name
			}
		}
		return nil, fmt.Errorf("executing JSONPath failed: %s is not found", name)
	case 1:
		return matches[0], nil
	default:
		return matches, nil
	}
}

func parseJSONPath(expr string) ([]jpSegment, error) {
	if !strings.HasPrefix(expr, "$") {
		return nil, fmt.Errorf("expression must start with '$'")
	}
	segs := []jpSegment{}
	i := 1
	for i < len(expr) {
		switch expr[i] {
		case '.':
			i++
			recurse := false
			if i < len(expr) && expr[i] == '.' {
				recurse = true
				i++
			}
			if i < len(expr) && expr[i] == '*' {
				i++
				if recurse {
					segs = append(segs, jpSegment{kind: jpRecurse, recChild: &jpSegment{kind: jpWildcard}})
				} else {
					segs = append(segs, jpSegment{kind: jpWildcard})
				}
				continue
			}
			start := i
			for i < len(expr) && expr[i] != '.' && expr[i] != '[' {
				i++
			}
			name := expr[start:i]
			if name == "" {
				return nil, fmt.Errorf("unexpected end of expression")
			}
			if recurse {
				segs = append(segs, jpSegment{kind: jpRecurse, recChild: &jpSegment{kind: jpChild, name: name}})
			} else {
				segs = append(segs, jpSegment{kind: jpChild, name: name})
			}
		case '[':
			end := strings.IndexByte(expr[i:], ']')
			if end < 0 {
				return nil, fmt.Errorf("unterminated array")
			}
			inner := strings.TrimSpace(expr[i+1 : i+end])
			i += end + 1
			switch {
			case inner == "*":
				segs = append(segs, jpSegment{kind: jpWildcard})
			case strings.HasPrefix(inner, "'") && strings.HasSuffix(inner, "'") && len(inner) >= 2,
				strings.HasPrefix(inner, `"`) && strings.HasSuffix(inner, `"`) && len(inner) >= 2:
				segs = append(segs, jpSegment{kind: jpChild, name: inner[1 : len(inner)-1]})
			default:
				idx, err := strconv.Atoi(inner)
				if err != nil {
					return nil, fmt.Errorf("unsupported array selector %q", inner)
				}
				segs = append(segs, jpSegment{kind: jpIndex, index: idx})
			}
		default:
			return nil, fmt.Errorf("unexpected character %q", expr[i])
		}
	}
	return segs, nil
}

func jpApply(s jpSegment, in []any) []any {
	out := []any{}
	for _, v := range in {
		if s.kind == jpRecurse {
			jpRecurseInto(*s.recChild, v, &out)
			continue
		}
		out = jpChildInto(s, v, out)
	}
	return out
}

func jpRecurseInto(s jpSegment, v any, out *[]any) {
	*out = jpChildInto(s, v, *out)
	switch t := v.(type) {
	case map[string]any:
		for _, e := range t {
			jpRecurseInto(s, e, out)
		}
	case []any:
		for _, e := range t {
			jpRecurseInto(s, e, out)
		}
	}
}

func jpChildInto(s jpSegment, v any, out []any) []any {
	switch s.kind {
	case jpChild:
		if m, ok := v.(map[string]any); ok {
			if e, ok := m[s.name]; ok {
				out = append(out, e)
			}
		}
	case jpIndex:
		if l, ok := v.([]any); ok {
			i := s.index
			if i < 0 {
				i += len(l)
			}
			if i >= 0 && i < len(l) {
				out = append(out, l[i])
			}
		}
	case jpWildcard:
		switch t := v.(type) {
		case map[string]any:
			keys := make([]string, 0, len(t))
			for k := range t {
				keys = append(keys, k)
			}
			sort := keys
			// deterministic order: sorted keys
			for i := 0; i < len(sort); i++ {
				for j := i + 1; j < len(sort); j++ {
					if sort[j] < sort[i] {
						sort[i], sort[j] = sort[j], sort[i]
					}
				}
			}
			for _, k := range sort {
				out = append(out, t[k])
			}
		case []any:
			out = append(out, t...)
		}
	}
	return out
}

