package coll

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// This is a small, self-contained subset of the jq language (the reference
// tool embeds a full external jq implementation, which cannot be reproduced
// with the Go standard library alone). Supported syntax:
//
//	.               identity
//	.name  .["name"]  object field (missing fields yield null)
//	.[n]            array index (negative counts from the end)
//	.[]             iterate over array elements / object values
//	|               pipe
//
// Anything else (functions, operators, constructions, filters...) returns a
// parse error.

type jqOp struct {
	kind int // jqIdentity, jqField, jqIndex, jqIterate
	name string
	idx  int
}

const (
	jqIdentity = iota
	jqField
	jqIndex
	jqIterate
)

// JQ filters the input using a jq expression. Multiple results are wrapped
// in an array; a single result is returned as-is.
func (n *ns) JQ(expression string, in any) (any, error) {
	ops, err := parseJQ(expression)
	if err != nil {
		return nil, fmt.Errorf("jq parsing expression %q: %s", expression, err)
	}
	results := []any{in}
	for _, op := range ops {
		next := []any{}
		for _, v := range results {
			var out []any
			out, err = jqApply(op, v)
			if err != nil {
				return nil, err
			}
			next = append(next, out...)
		}
		results = next
	}
	switch len(results) {
	case 0:
		return nil, nil
	case 1:
		return results[0], nil
	default:
		return results, nil
	}
}

var jqWordRe = regexp.MustCompile(`[a-zA-Z0-9_]+`)

func parseJQ(expr string) ([]jqOp, error) {
	ops := []jqOp{}
	i := 0
	expectTerm := true
	for i < len(expr) {
		c := expr[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n':
			i++
		case c == '|':
			if expectTerm {
				return nil, fmt.Errorf("unexpected token %q", "|")
			}
			expectTerm = true
			i++
		case c == '.':
			if !expectTerm {
				return nil, fmt.Errorf("unexpected token %q", ".")
			}
			expectTerm = false
			i++
			if i >= len(expr) {
				ops = append(ops, jqOp{kind: jqIdentity})
				continue
			}
			switch expr[i] {
			case '[':
				end := strings.IndexByte(expr[i:], ']')
				if end < 0 {
					return nil, fmt.Errorf("unexpected EOF")
				}
				inner := strings.TrimSpace(expr[i+1 : i+end])
				i += end + 1
				switch {
				case inner == "":
					ops = append(ops, jqOp{kind: jqIterate})
				case strings.HasPrefix(inner, `"`) && strings.HasSuffix(inner, `"`) && len(inner) >= 2:
					name, err := strconv.Unquote(inner)
					if err != nil {
						return nil, fmt.Errorf("unexpected token %q", inner)
					}
					ops = append(ops, jqOp{kind: jqField, name: name})
				default:
					idx, err := strconv.Atoi(inner)
					if err != nil {
						return nil, fmt.Errorf("unexpected token %q", inner)
					}
					ops = append(ops, jqOp{kind: jqIndex, idx: idx})
				}
			case expr[i] == '.' :
				// recursive descent is not supported
				return nil, fmt.Errorf("unexpected token %q", "..")
			default:
				start := i
				for i < len(expr) && (expr[i] >= 'a' && expr[i] <= 'z' ||
					expr[i] >= 'A' && expr[i] <= 'Z' ||
					expr[i] >= '0' && expr[i] <= '9' || expr[i] == '_') {
					i++
				}
				if start == i {
					return nil, fmt.Errorf("unexpected token %q", string(expr[i]))
				}
				ops = append(ops, jqOp{kind: jqField, name: expr[start:i]})
			}
		default:
			// not a path expression: report the last word token, matching the
			// reference parser's behaviour for plain words (e.g. "not jq!!"
			// reports "jq")
			words := jqWordRe.FindAllString(expr, -1)
			if len(words) == 0 {
				return nil, fmt.Errorf("unexpected token %q", string(c))
			}
			return nil, fmt.Errorf("unexpected token %q", words[len(words)-1])
		}
	}
	if expectTerm && len(ops) > 0 {
		return nil, fmt.Errorf("unexpected EOF")
	}
	if len(ops) == 0 {
		return nil, fmt.Errorf("unexpected EOF")
	}
	return ops, nil
}

func jqApply(op jqOp, v any) ([]any, error) {
	switch op.kind {
	case jqIdentity:
		return []any{v}, nil
	case jqField:
		if v == nil {
			return []any{nil}, nil
		}
		m, ok := v.(map[string]any)
		if !ok {
			return nil, fmt.Errorf("jq execution failed: cannot index %T with %q", v, op.name)
		}
		return []any{m[op.name]}, nil
	case jqIndex:
		if v == nil {
			return []any{nil}, nil
		}
		l, ok := v.([]any)
		if !ok {
			return nil, fmt.Errorf("jq execution failed: cannot index %T with %d", v, op.idx)
		}
		i := op.idx
		if i < 0 {
			i += len(l)
		}
		if i < 0 || i >= len(l) {
			return []any{nil}, nil
		}
		return []any{l[i]}, nil
	case jqIterate:
		switch t := v.(type) {
		case []any:
			return append([]any{}, t...), nil
		case map[string]any:
			keys := make([]string, 0, len(t))
			for k := range t {
				keys = append(keys, k)
			}
			sortStrings(keys)
			out := make([]any, 0, len(t))
			for _, k := range keys {
				out = append(out, t[k])
			}
			return out, nil
		}
		return nil, fmt.Errorf("jq execution failed: cannot iterate over %T", v)
	}
	return nil, nil
}

