}

// tailAfterPos strips the "template: <arg>:1:14: " position prefix, which we
// cannot reproduce identically (positions depend on the binary's parsing).
func tailAfterPos(refMsg string) string {
	// refMsg looks like: template: <arg>:1:31: executing "<arg>" at <...>
	if i := strings.Index(refMsg, ": executing "); i >= 0 {
		return refMsg[i+2:]
	}
	return refMsg
}

